const regulationDocx = "";
for (const link of document.querySelectorAll("[data-regulation-docx]")) {
  const bytes = Uint8Array.from(atob(regulationDocx), char => char.charCodeAt(0));
  link.href = URL.createObjectURL(new Blob([bytes], {type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document"}));
  link.hidden = false;
}
